type agreementDiagnosticLiveSource struct {
	Original, Projected agreementDestinationLiveSource
	Shapes, AfterShapes []agreementDestinationLiveField
	Tuples              map[agreementCitation]int
	Valid               bool
}

// A visible occurrence cannot lend its diagnostic to an erased declaration.
// Keep every outside field and change only occupied target bytes in a private
// copy, retaining all native owners, positions and non-target spelling.
func agreementDiagnosticLiveReading(body string) (reading agreementDiagnosticLiveSource, projected string) {
	r := agreementDiagnosticLiveSource{Original: agreementDestinationLiveReading(body), Tuples: make(map[agreementCitation]int)}
	before := &r.Original
	if len(before.Owned.Fields) == 0 {
		return r, ""
	}
	ordinary, inactive := make(map[string]bool), make(map[string]bool)
	for i := range before.Owned.Fields {
		field := &before.Owned.Fields[i]
		if field.Tuple.SourceRole == "" {
			r.Tuples[field.Tuple]++
			ordinary[field.Tuple.Target] = true
		} else {
			inactive[field.Tuple.Target] = true
		}
	}
	projected, valid := agreementDestinationLiveProjection(body, before)
	if !valid {
		return r, ""
	}
	r.Projected = agreementDestinationLiveReading(projected)
	after := &r.Projected
	var beforeValid, afterValid bool
	r.Shapes, beforeValid = agreementDestinationLiveShapes(body, before)
	r.AfterShapes, afterValid = agreementDestinationLiveShapes(projected, after)
	r.Valid = len(r.Tuples) != 0 && beforeValid && afterValid && cmp.Equal(r.Shapes, r.AfterShapes) &&
		cmp.Equal(before.Owned.Page, after.Owned.Page) && cmp.Equal(before.Owned.Check.Code, after.Owned.Check.Code) &&
		cmp.Equal(before.Owned.Check.Comments, after.Owned.Check.Comments) && cmp.Equal(before.Owned.Fields, after.Owned.Fields) && cmp.Equal(before.Names, after.Names)
	for name := range ordinary {
		if inactive[name] {
			r.Valid = false
		}
	}
	for _, reading := range []*agreementDestinationLiveSource{before, after} {
		var owned []agreementNativeCheckField
		for i := range reading.Owned.Fields {
			field := &reading.Owned.Fields[i]
			owned = append(owned, field.Source)
		}
		input := body
		if reading == after {
			input = projected
		}
		ledger := agreementOwnedCheckLiveSource{Native: reading.Owned.Page, Check: reading.Owned.Check, Owned: owned, Outside: reading.Outside, Names: reading.Names, Page: reading.Page}
		r.Valid = r.Valid && agreementOwnedCheckLiveLedger(input, &ledger)
	}
	return r, projected
}

// Count the whole broken-wikilink pool. Block-addressed or empty-target
// diagnostics belong to another source role and cannot supply these tuples.
func agreementDiagnosticLiveDiagnostics(diagnostics []render.Diagnostic) (map[agreementCitation]int, bool) {
	counts := make(map[agreementCitation]int)
	for _, diagnostic := range diagnostics {
		if diagnostic.Kind != render.DiagWikilinkBroken {
			continue
		}
		if diagnostic.Target == "" || diagnostic.Block != "" {
			return nil, false
		}
		counts[agreementCitation{Target: diagnostic.Target, Section: diagnostic.Section, State: "wikilink-broken"}]++
	}
	return counts, true
}

type agreementDiagnosticLivePayload struct {
	Body                                         string
	Source                                       agreementDiagnosticLiveSource
	Page, Diagnostics, WitnessPage, WitnessDiags map[agreementCitation]int
}

func agreementDiagnosticLiveEvidence(p *agreementDiagnosticLivePayload) bool {
	if !p.Source.Valid || len(p.Page) == 0 || !cmp.Equal(p.Page, p.Source.Original.Page) || !cmp.Equal(p.WitnessPage, p.Source.Projected.Page) {
		return false
	}
	for tuple := range p.WitnessPage {
		if p.Source.Original.Names[tuple.Target] {
			return false
		}
	}
	original, projected := maps.Clone(p.Source.Original.Page), maps.Clone(p.Source.Projected.Page)
	for tuple, count := range p.Source.Tuples {
		original[tuple] += count
		projected[tuple] += count
	}
	return cmp.Equal(original, p.Diagnostics) && cmp.Equal(projected, p.WitnessDiags)
}

func agreementDiagnosticLiveBudget(t *testing.T, body string, actual *agreementHTML, diagnostics []render.Diagnostic) agreementDiagnosticLivePayload {
	t.Helper()
	source, projected := agreementDiagnosticLiveReading(body)
	if !source.Valid || len(actual.Citations) == 0 {
		return agreementDiagnosticLivePayload{}
	}
	rendered, witness := agreementIsolatedPage(t, agreementCase{Body: projected})
	before, beforeValid := agreementDiagnosticLiveDiagnostics(diagnostics)
	after, afterValid := agreementDiagnosticLiveDiagnostics(rendered.Diagnostics)
	if !beforeValid || !afterValid {
		return agreementDiagnosticLivePayload{}
	}
	payload := agreementDiagnosticLivePayload{Body: body, Source: source, Page: agreementNativeLiveCarriers(actual), Diagnostics: before, WitnessPage: agreementNativeLiveCarriers(&witness), WitnessDiags: after}
	if !agreementDiagnosticLiveEvidence(&payload) {
		return agreementDiagnosticLivePayload{}
	}
	return payload
}

func agreementDiagnosticLiveDifference(c agreementCase, f *agreementFailure, actual *agreementHTML, diagnostics []render.Diagnostic, budget *agreementDiagnosticLivePayload) (kind, authority, wrong string) {
	source, _ := agreementDiagnosticLiveReading(c.Body)
	current, valid := agreementDiagnosticLiveDiagnostics(diagnostics)
	if !cmp.Equal(source, budget.Source) || !valid || !cmp.Equal(current, budget.Diagnostics) || !cmp.Equal(agreementNativeLiveCarriers(actual), budget.Page) || !agreementDiagnosticLiveEvidence(budget) {
		return "", "", ""
	}
	return agreementSharedUnusedDiagnosticDifference(c, f, actual, diagnostics, agreementUnusedWidgetPayload{Body: budget.Body, Tuples: budget.Source.Tuples})
}

