func TestAgreementDiagnosticLiveSource(t *testing.T) {
	t.Parallel()
	cases := agreementDiagnosticLiveControls()
	for i := range cases {
		tc := &cases[i]
		t.Run(tc.Name, func(t *testing.T) {
			t.Parallel()
			source, projected := agreementDiagnosticLiveReading(tc.Body)
			if diff := cmp.Diff(tc.Source, source); diff != "" {
				t.Fatalf("caught: complete diagnostic live source (-want +got):\n%s", diff)
			}
			if projected != tc.Projection {
				t.Fatalf("caught: complete diagnostic live projection got=%q want=%q", projected, tc.Projection)
			}
		})
	}
}

func TestAgreementDiagnosticLivePublic(t *testing.T) {
	t.Parallel()
	cases := agreementDiagnosticLiveControls()
	for i := range cases {
		tc := &cases[i]
		t.Run(tc.Name, func(t *testing.T) {
			t.Parallel()
			c := agreementCase{Body: tc.Body}
			r, a := agreementIsolatedPage(t, c)
			payload := agreementDiagnosticLiveBudget(t, c.Body, &a, r.Diagnostics)
			if diff := cmp.Diff(tc.Payload, payload); diff != "" {
				t.Fatalf("caught: complete diagnostic live public budget (-want +got):\n%s", diff)
			}
			owned := make(map[string]int)
			for _, f := range agreementPageFailures(c.Body, &r, &a) {
				kind, authority, wrong := agreementDiagnosticLiveDifference(c, &f, &a, r.Diagnostics, &payload)
				if kind == "" {
					continue
				}
				if kind != "debt" || authority != "#1011 stage 5" || wrong != "page-diagnostic" {
					t.Fatalf("caught: diagnostic live public ownership %q %q %q", kind, authority, wrong)
				}
				owned[agreementSignature(&f)+" / "+kind+" / "+authority+" / "+wrong]++
				agreementDiagnosticLiveDrift(t, c, &f, &a, r.Diagnostics, &payload)
			}
			if diff := cmp.Diff(tc.Owned, owned); diff != "" {
				t.Fatalf("caught: complete diagnostic live public receipts (-want +got):\n%s", diff)
			}
		})
	}
}

func agreementDiagnosticLiveDrift(t *testing.T, c agreementCase, f *agreementFailure, a *agreementHTML, diagnostics []render.Diagnostic, p *agreementDiagnosticLivePayload) {
	t.Helper()
	for _, other := range []agreementCase{{Body: c.Body + "unowned"}, {Body: c.Body, Title: "title"}, {Body: c.Body, Companions: capturedBodies{"A.md": "words"}}} {
		if kind, _, _ := agreementDiagnosticLiveDifference(other, f, a, diagnostics, p); kind != "" {
			t.Fatal("caught: diagnostic live borrowed source or vault context")
		}
	}
	for _, change := range []func(*agreementFailure){
		func(f *agreementFailure) { f.Property = "unowned" }, func(f *agreementFailure) { f.Identity = "unowned" }, func(f *agreementFailure) { f.Direction = "unowned" }, func(f *agreementFailure) { f.Tuple.Target = "unowned" }, func(f *agreementFailure) { f.Tuple.Section = "unowned" }, func(f *agreementFailure) { f.Tuple.SourceRole = "unowned" }, func(f *agreementFailure) { f.Tuple.State = "unowned" }, func(f *agreementFailure) { f.Fragment = "unowned" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Multiplicity = 0 }, func(f *agreementFailure) { f.Multiplicity = -1 }, func(f *agreementFailure) { f.PagePresent = true }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true }, func(f *agreementFailure) { f.Cut = "unowned" },
	} {
		other := *f
		change(&other)
		if kind, _, _ := agreementDiagnosticLiveDifference(c, &other, a, diagnostics, p); kind != "" {
			t.Fatalf("caught: diagnostic live borrowed signature %s", agreementSignature(&other))
		}
	}
	for _, citations := range [][]agreementCitation{nil, a.Citations[:len(a.Citations)-1], append(slices.Clone(a.Citations), agreementCitation{Target: "unowned", State: "wikilink-broken"})} {
		other := *a
		other.Citations = citations
		if kind, _, _ := agreementDiagnosticLiveDifference(c, f, &other, diagnostics, p); kind != "" {
			t.Fatal("caught: diagnostic live borrowed changed whole page pool")
		}
		if agreementDiagnosticLiveBudget(t, c.Body, &other, diagnostics).Body != "" {
			t.Fatal("caught: diagnostic live budget borrowed changed whole page pool")
		}
	}
	for _, replacement := range [][]render.Diagnostic{nil, append(slices.Clone(diagnostics), render.Diagnostic{Kind: render.DiagWikilinkBroken, Target: "unowned"})} {
		if kind, _, _ := agreementDiagnosticLiveDifference(c, f, a, replacement, p); kind != "" {
			t.Fatal("caught: diagnostic live borrowed changed whole diagnostic pool")
		}
		if agreementDiagnosticLiveBudget(t, c.Body, a, replacement).Body != "" {
			t.Fatal("caught: diagnostic live budget borrowed changed whole diagnostic pool")
		}
	}
	for _, change := range []func(*agreementDiagnosticLivePayload){
		func(p *agreementDiagnosticLivePayload) { p.Page = map[agreementCitation]int{} },
		func(p *agreementDiagnosticLivePayload) { p.Diagnostics = map[agreementCitation]int{} },
		func(p *agreementDiagnosticLivePayload) { p.WitnessPage = map[agreementCitation]int{} },
		func(p *agreementDiagnosticLivePayload) { p.WitnessDiags = map[agreementCitation]int{} },
		func(p *agreementDiagnosticLivePayload) {
			p.WitnessPage = maps.Clone(p.WitnessPage)
			p.WitnessPage[agreementCitation{Target: "unowned", State: "wikilink-broken"}]++
		},
		func(p *agreementDiagnosticLivePayload) {
			p.WitnessDiags = maps.Clone(p.WitnessDiags)
			p.WitnessDiags[agreementCitation{Target: "unowned", State: "wikilink-broken"}]++
		},
	} {
		other := *p
		change(&other)
		if kind, _, _ := agreementDiagnosticLiveDifference(c, f, a, diagnostics, &other); kind != "" {
			t.Fatal("caught: diagnostic live borrowed changed original or projected whole pool")
		}
	}
}

func TestAgreementDiagnosticLiveSourceDrift(t *testing.T) {
	t.Parallel()
	body := "ghost [[A#part|shown]] [[B#^a|pic]] \\[[C]] %%[[D]]%%\n\n[^n]: [[A]] [[B]] `[[E]]` \\[[F]]\n"
	c := agreementCase{Body: body}
	r, a := agreementIsolatedPage(t, c)
	baseline := agreementDiagnosticLiveBudget(t, body, &a, r.Diagnostics)
	if baseline.Body == "" || len(baseline.Source.Original.Owned.Page.Definitions) != 1 || len(baseline.Source.Original.Owned.Page.Code) != 1 || len(baseline.Source.Original.Owned.Fields) != 4 || len(baseline.Source.Original.Owned.Check.Fields) != 8 || len(baseline.Source.Original.Outside) != 4 || len(baseline.Source.Shapes) != 4 || len(baseline.Source.Original.Owned.Page.Definitions[0].Nodes) < 3 {
		t.Fatal("caught: diagnostic live source drift lacks complete declared shape")
	}
	var failure *agreementFailure
	for _, f := range agreementPageFailures(body, &r, &a) {
		if kind, _, _ := agreementDiagnosticLiveDifference(c, &f, &a, r.Diagnostics, &baseline); kind != "" {
			owned := f
			failure = &owned
			break
		}
	}
	if failure == nil {
		t.Fatal("caught: diagnostic live source drift control is unowned")
	}
	changes := []struct {
		name   string
		change func(*agreementDiagnosticLiveSource)
	}{
		{"validity", func(s *agreementDiagnosticLiveSource) { s.Valid = false }},
		{"whole original", func(s *agreementDiagnosticLiveSource) { s.Original = agreementDestinationLiveSource{} }},
		{"whole projection", func(s *agreementDiagnosticLiveSource) { s.Projected = agreementDestinationLiveSource{} }},
		{"original definitions", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Definitions = nil }},
		{"original label", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Definitions[0].Label = "unowned" }},
		{"original parent", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Definitions[0].Parent = "unowned" }},
		{"original consumed span", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Definitions[0].Span.Stop-- }},
		{"original label span", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Definitions[0].Name.Start++ }},
		{"original child set", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Definitions[0].Nodes = nil }},
		{"original child kind", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Definitions[0].Nodes[1].Kind = "unowned" }},
		{"original child depth", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Definitions[0].Nodes[1].Depth++ }},
		{"original child lines", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Definitions[0].Nodes[1].Lines = nil }},
		{"original child text", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Definitions[0].Nodes[2].Text = nil }},
		{"original code", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Code = nil }},
		{"original code kind", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Code[0].Kind = "unowned" }},
		{"original code parent", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Code[0].Parent = "unowned" }},
		{"original code span", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Code[0].Span.Start++ }},
		{"original comments", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Page.Comments = nil }},
		{"original check code", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Check.Code = nil }},
		{"original check comments", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Check.Comments = nil }},
		{"original check fields", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Check.Fields = nil }},
		{"original check targets", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Check.Targets = nil }},
		{"original owned fields", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Fields = nil }},
		{"original owned tuple", func(s *agreementDiagnosticLiveSource) { s.Original.Owned.Fields[0].Tuple.Section = "unowned" }},
		{"original outside fields", func(s *agreementDiagnosticLiveSource) { s.Original.Outside = nil }},
		{"original outside raw", func(s *agreementDiagnosticLiveSource) { s.Original.Outside[0].Source.Word += "unowned" }},
		{"original outside span", func(s *agreementDiagnosticLiveSource) { s.Original.Outside[0].Source.Span.Stop++ }},
		{"original outside role", func(s *agreementDiagnosticLiveSource) { s.Original.Outside[0].Cites = false }},
		{"original outside block", func(s *agreementDiagnosticLiveSource) { s.Original.Outside[1].Block = "unowned" }},
		{"original names", func(s *agreementDiagnosticLiveSource) { s.Original.Names = nil }},
		{"original page set", func(s *agreementDiagnosticLiveSource) { s.Original.Page = nil }},
		{"projected definitions", func(s *agreementDiagnosticLiveSource) { s.Projected.Owned.Page.Definitions = nil }},
		{"projected code", func(s *agreementDiagnosticLiveSource) { s.Projected.Owned.Page.Code = nil }},
		{"projected comments", func(s *agreementDiagnosticLiveSource) { s.Projected.Owned.Page.Comments = nil }},
		{"projected check code", func(s *agreementDiagnosticLiveSource) { s.Projected.Owned.Check.Code = nil }},
		{"projected check comments", func(s *agreementDiagnosticLiveSource) { s.Projected.Owned.Check.Comments = nil }},
		{"projected check fields", func(s *agreementDiagnosticLiveSource) { s.Projected.Owned.Check.Fields = nil }},
		{"projected check targets", func(s *agreementDiagnosticLiveSource) { s.Projected.Owned.Check.Targets = nil }},
		{"projected owned fields", func(s *agreementDiagnosticLiveSource) { s.Projected.Owned.Fields = nil }},
		{"projected outside fields", func(s *agreementDiagnosticLiveSource) { s.Projected.Outside = nil }},
		{"projected names", func(s *agreementDiagnosticLiveSource) { s.Projected.Names = nil }},
		{"projected page set", func(s *agreementDiagnosticLiveSource) { s.Projected.Page = nil }},
		{"whole original shapes", func(s *agreementDiagnosticLiveSource) { s.Shapes = nil }},
		{"original shape words", func(s *agreementDiagnosticLiveSource) { s.Shapes[0].Source.Word += "unowned" }},
		{"original shape order", func(s *agreementDiagnosticLiveSource) { s.Shapes[0], s.Shapes[1] = s.Shapes[1], s.Shapes[0] }},
		{"whole projected shapes", func(s *agreementDiagnosticLiveSource) { s.AfterShapes = nil }},
		{"projected shape span", func(s *agreementDiagnosticLiveSource) { s.AfterShapes[0].Source.Span.Stop++ }},
		{"whole owned tuples", func(s *agreementDiagnosticLiveSource) { s.Tuples = nil }},
		{"foreign owned tuple", func(s *agreementDiagnosticLiveSource) {
			s.Tuples[agreementCitation{Target: "unowned", State: "wikilink-broken"}]++
		}},
	}
	for i := range changes {
		change := &changes[i]
		t.Run(change.name, func(t *testing.T) {
			t.Parallel()
			payload := baseline
			payload.Source, _ = agreementDiagnosticLiveReading(body)
			change.change(&payload.Source)
			if kind, _, _ := agreementDiagnosticLiveDifference(c, failure, &a, r.Diagnostics, &payload); kind != "" {
				t.Fatal("caught: diagnostic live borrowed changed complete source")
			}
		})
	}
	other := agreementCase{Body: strings.Replace(body, "ghost", "shade", 1)}
	same, _ := agreementDiagnosticLiveReading(other.Body)
	if !cmp.Equal(baseline.Source, same) {
		t.Fatal("caught: diagnostic live body-only drift changed declared facts")
	}
	if kind, _, _ := agreementDiagnosticLiveDifference(other, failure, &a, r.Diagnostics, &baseline); kind != "" {
		t.Fatal("caught: diagnostic live borrowed different bytes with identical declared facts")
	}
}

func TestAgreementDiagnosticLiveDiagnosticRoles(t *testing.T) {
	t.Parallel()
	for _, tc := range []struct {
		name        string
		diagnostics []render.Diagnostic
		want        map[agreementCitation]int
		valid       bool
	}{
		{name: "whole ordered pool", diagnostics: []render.Diagnostic{{Kind: render.DiagWikilinkBroken, Target: "A"}, {Kind: render.DiagWikilinkBroken, Target: "A", Section: "part"}, {Kind: render.DiagWikilinkBroken, Target: "A"}}, want: map[agreementCitation]int{{Target: "A", State: "wikilink-broken"}: 2, {Target: "A", Section: "part", State: "wikilink-broken"}: 1}, valid: true},
		{name: "empty pool", want: map[agreementCitation]int{}, valid: true},
		{name: "other kind does not supply tuple", diagnostics: []render.Diagnostic{{Kind: render.DiagUnknownCallout, Target: "A"}}, want: map[agreementCitation]int{}, valid: true},
		{name: "block role refuses whole pool", diagnostics: []render.Diagnostic{{Kind: render.DiagWikilinkBroken, Target: "A"}, {Kind: render.DiagWikilinkBroken, Target: "A", Block: "^a"}}},
		{name: "empty target refuses whole pool", diagnostics: []render.Diagnostic{{Kind: render.DiagWikilinkBroken, Target: "A"}, {Kind: render.DiagWikilinkBroken}}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			got, valid := agreementDiagnosticLiveDiagnostics(tc.diagnostics)
			if !cmp.Equal(tc.want, got) || valid != tc.valid {
				t.Fatalf("caught: complete diagnostic live diagnostic roles got=%#v valid=%t want=%#v valid=%t", got, valid, tc.want, tc.valid)
			}
		})
	}
}
